R_PG = set("ALL ANALYSE ANALYZE AND ANY ARRAY AS ASC ASYMMETRIC BOTH CASE CAST CHECK COLLATE COLUMN CONSTRAINT CREATE DEFAULT DEFERRABLE DESC DISTINCT DO ELSE END EXCEPT FALSE FETCH FOR FOREIGN FROM GRANT GROUP HAVING IN INITIALLY INTERSECT INTO LATERAL LEADING LIMIT NOT NULL OFFSET ON ONLY OR ORDER PLACING PRIMARY REFERENCES RETURNING SELECT SOME SYMMETRIC TABLE THEN TO TRAILING TRUE UNION UNIQUE USER USING VARIADIC WHEN WHERE WINDOW WITH".split())
R_SQLITE = set("ABORT ACTION ADD ALL ALTER AND AS ASC BETWEEN BY CASE CHECK COLUMN COMMIT CONSTRAINT CREATE CROSS DEFAULT DELETE DESC DISTINCT DROP ELSE END ESCAPE EXCEPT EXISTS FOR FOREIGN FROM FULL GLOB GROUP HAVING IF IN INDEX INNER INSERT INTERSECT INTO IS JOIN KEY LEFT LIKE LIMIT MATCH NATURAL NO NOT NULL OF ON OR ORDER OUTER PLAN PRIMARY QUERY RANGE REFERENCES REPLACE RIGHT ROW ROWS SELECT SET TABLE TEMP THEN TO TRIGGER UNION UNIQUE UPDATE USING VALUES VIEW WHEN WHERE WINDOW WITH".split())

def reserved(name):
    u = name.upper(); out = []
    if u in R_SQLITE: out.append("SQLite")
    if u in R_MSSQL: out.append("MSSQL")
    if u in R_PG: out.append("PG")
    return out

def ident_issues(name):
    iss = []
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
        if name[0].isdigit(): iss.append("leading digit")
        chars = sorted({c for c in name if not re.match(r"[A-Za-z0-9_]", c)})
        if chars: iss.append("special chars " + "".join(repr(c) if c == " " else c for c in chars))
    if not name.isascii(): iss.append("non-ASCII")
    if name != name.upper() and name != name.lower() and False: iss.append("mixed case")
    return iss

def shapes(db):
    sh = collections.defaultdict(list)
    for n, t in S[db]["tables"].items():
        sh[tuple((c["name"], c["type"], c["size"]) for c in t["columns"])].append(n)
    return sorted(sh.items(), key=lambda x: (-len(x[1]), x[1][0]))

def shape_names_only(db):
    sh = collections.defaultdict(list)
    for n, t in S[db]["tables"].items():
        sh[tuple(c["name"] for c in t["columns"])].append(n)
    return sh

def best_key(db, n):
    kcs = P[db]["tables"][n]["key_checks"]
    good = [k for k in kcs if k["distinct"] == k["rows"] and k["null_or_empty"] == 0 and k["rows"] > 0]
    nat = [k for k in good if k["cols"] != ["RECNUM"]]
    # natural keys: exclude COUNTER-only
    nat_ci = [k for k in nat if k["distinct_ci_trim"] == k["rows"]]
    return nat_ci, nat

def fmtcols(cols): return "(" + ", ".join(cols) + ")"

def tsv(n): return f"{n:,}"

# ---------------- detail ----------------
def write_detail():
    L = ["# Schema inventory - per-table detail (generated)", "",
         "Generated by `scripts/inspect/05_generate_docs.py` from `scripts/inspect/out/*.json`. Do not hand-edit.", "",
         "Columns: ODBC type_name, column_size, decimal_digits, nullable (as reported by the driver), then observed NULL count, empty-string count, max observed length, count of values with non-ASCII, count with leading/trailing whitespace. Full scans, no sampling.", ""]
    for db, fn in DBS:
        L += [f"## {fn}", ""]
        for n, t in S[db]["tables"].items():
            p = P[db]["tables"][n]
            L.append(f"### `{n}`  rows={tsv(t['rows'])}")
            ix = "; ".join(f"{k} {'UNIQUE ' if v['unique'] else ''}{fmtcols([c for _, c in sorted(v['cols'])])}" for k, v in t["indexes"].items()) or "none reported"
            L.append(f"Indexes: {ix}")
            nat_ci, nat = best_key(db, n)
            L.append("Key checks (distinct/rows, null-or-empty): " + "; ".join(
                f"{fmtcols(k['cols'])} {k['distinct']}/{k['rows']} (ci+trim {k['distinct_ci_trim']}) nulls={k['null_or_empty']}" for k in p["key_checks"]))
            L.append(f"Duplicate rows excluding RECNUM: exact={p['dup_rows_excl_counter']}, case-insensitive+trim={p['dup_rows_excl_counter_ci']}")
            L += ["", "| column | type | size | digits | nullable | NULLs | empty | maxlen | non-ASCII | ws | num-like |", "|---|---|---|---|---|---|---|---|---|---|---|"]
            for c in t["columns"]:
                s = p["cols"][c["name"]]
                L.append(f"| {c['name']} | {c['type']} | {c['size']} | {c['digits']} | {'Y' if c['nullable'] else 'N'} | {s['null']} | {s['empty']} | {s['maxlen']} | {s['nonascii']} | {s['lead_trail_ws']} | {s['numeric_like']} |")
            L.append("")
    open(os.path.join(DOCS, "schema_inventory_detail.md"), "w", encoding="utf-8").write("\n".join(L))

